class PageUtil:
    PAGE_SIZE_DEFAULT = 10
    MIN_PAGE_NUMBER = 1

    def __init__(self, data, page_size):
        self.data = data
        self.page_size = page_size
        self.total_items = len(data)
        self.total_pages = self._calculate_total_pages(self.total_items, self.page_size)

    def _calculate_total_pages(self, total_items, page_size):
        return (total_items + page_size - 1) // page_size

    def _is_valid_page(self, page_number):
        return PageUtil.MIN_PAGE_NUMBER <= page_number <= self.total_pages

    def _get_start_index(self, page_number):
        return (page_number - PageUtil.MIN_PAGE_NUMBER) * self.page_size

    def _get_end_index(self, page_number):
        start_index = self._get_start_index(page_number)
        return min(start_index + self.page_size, self.total_items)

    def get_page(self, page_number):
        if not self._is_valid_page(page_number):
            return []

        start_index = self._get_start_index(page_number)
        end_index = start_index + self.page_size
        return self.data[start_index:end_index]

    def get_page_info(self, page_number):
        if not self._is_valid_page(page_number):
            return {}

        start_index = self._get_start_index(page_number)
        end_index = self._get_end_index(page_number)
        page_data = self.data[start_index:end_index]

        page_info = {
            "current_page": page_number,
            "per_page": self.page_size,
            "total_pages": self.total_pages,
            "total_items": self.total_items,
            "has_previous": self._has_previous_page(page_number),
            "has_next": self._has_next_page(page_number),
            "data": page_data
        }
        return page_info

    def _has_previous_page(self, page_number):
        return page_number > PageUtil.MIN_PAGE_NUMBER

    def _has_next_page(self, page_number):
        return page_number < self.total_pages

    def search(self, keyword):
        results = [item for item in self.data if keyword in str(item)]
        search_info = {
            "keyword": keyword,
            "total_results": len(results),
            "total_pages": self._calculate_total_pages(len(results), self.page_size),
            "results": results
        }
        return search_info
